import{_ as a,o as r,c as e,a3 as o}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"悬浮窗操作技巧","description":"","frontmatter":{},"headers":[],"relativePath":"use/gestures.md","filePath":"use/gestures.md","lastUpdated":1791133906000}'),s={name:"use/gestures.md"};function l(d,t,n,i,h,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="悬浮窗操作技巧" tabindex="-1">悬浮窗操作技巧 <a class="header-anchor" href="#悬浮窗操作技巧" aria-label="Permalink to &quot;悬浮窗操作技巧&quot;">​</a></h1><p>悬浮窗和面板的手感是手机游戏内最容易出问题的部分。本篇汇总操作技巧和设计考虑。</p><h2 id="悬浮窗操作" tabindex="-1">悬浮窗操作 <a class="header-anchor" href="#悬浮窗操作" aria-label="Permalink to &quot;悬浮窗操作&quot;">​</a></h2><h3 id="点一下-打开面板" tabindex="-1">点一下 = 打开面板 <a class="header-anchor" href="#点一下-打开面板" aria-label="Permalink to &quot;点一下 = 打开面板&quot;">​</a></h3><p>轻点悬浮窗（不要按住拖），打开控制台。</p><h3 id="拖动-换位置" tabindex="-1">拖动 = 换位置 <a class="header-anchor" href="#拖动-换位置" aria-label="Permalink to &quot;拖动 = 换位置&quot;">​</a></h3><p>按住悬浮窗拖动，可以把它挪到屏幕任意位置。</p><p><strong>位置会被记住。</strong></p><h3 id="收起面板" tabindex="-1">收起面板 <a class="header-anchor" href="#收起面板" aria-label="Permalink to &quot;收起面板&quot;">​</a></h3><ul><li><strong>点面板外面</strong>（灰色遮罩区）→ 收起</li><li>收起后悬浮窗还在，可以再点开</li></ul><h2 id="推荐的位置" tabindex="-1">推荐的位置 <a class="header-anchor" href="#推荐的位置" aria-label="Permalink to &quot;推荐的位置&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">千万别放在屏幕右下角</p><p>右下角通常有<strong>战斗按钮</strong>（射击、机动等）。</p><p>悬浮窗放在那里会<strong>挡住按钮的点击</strong>，表现为「我点射击，但没反应」。</p><p><strong>这不是框架的 bug，是位置重叠导致的点击被吃掉。</strong></p></div><p><strong>推荐放屏幕上方</strong>（顶部中间或顶部两侧）。那里通常没有操作按钮。</p><p>如果悬浮窗挡到了什么，直接拖走即可。</p><h2 id="为什么有些点击收不到" tabindex="-1">为什么有些点击收不到 <a class="header-anchor" href="#为什么有些点击收不到" aria-label="Permalink to &quot;为什么有些点击收不到&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">一个安卓上的真实问题</p><p>部分安卓设备在<strong>抬手</strong>时会收不到界面点击事件（这是系统层面的输入事件问题）。</p><p>后果：你点了悬浮窗，但框架没收到「点击」这个事件，面板打不开，<strong>而且不知道为什么</strong>。</p></div><p>框架为此做了<strong>三重保险</strong>：</p><h3 id="保险-1-点击超时兜底" tabindex="-1">保险 ①：点击超时兜底 <a class="header-anchor" href="#保险-1-点击超时兜底" aria-label="Permalink to &quot;保险 ①：点击超时兜底&quot;">​</a></h3><p>按下后，如果在一小段时间内<strong>没有检测到移动</strong>，就按「点击」处理（而不是等一个可能永远不来的抬手事件）。</p><p>用的是真实运行时间，所以即使游戏暂停也不影响。</p><h3 id="保险-2-位移阈值按屏幕比例" tabindex="-1">保险 ②：位移阈值按屏幕比例 <a class="header-anchor" href="#保险-2-位移阈值按屏幕比例" aria-label="Permalink to &quot;保险 ②：位移阈值按屏幕比例&quot;">​</a></h3><p>判断「点击」还是「拖动」，用的阈值是<strong>按屏幕宽度算比例</strong>的，不是固定像素值。</p><div class="warning custom-block"><p class="custom-block-title">为什么不能用固定像素</p><p>手机上手指按下去必然有轻微抖动。如果阈值是固定的 6 像素，<strong>几乎每次点按都会被判成拖动</strong> —— 结果就是「永远打不开面板」。</p><p>所以要按屏幕大小算（<code>屏宽 × 2%</code>，最小 12 像素）。</p></div><h3 id="保险-3-三指手势" tabindex="-1">保险 ③：三指手势 <a class="header-anchor" href="#保险-3-三指手势" aria-label="Permalink to &quot;保险 ③：三指手势&quot;">​</a></h3><p><strong>三根手指同时按屏幕</strong> → 强制唤起面板。</p><p>这是完全独立的通道，走的是触摸列表，<strong>不依赖任何点击事件</strong>。</p><div class="tip custom-block"><p class="custom-block-title">记住这个手势</p><p>如果哪天悬浮窗点不动了，<strong>三指同按</strong>是最可靠的救命手势。</p></div><h2 id="点击目标的大小" tabindex="-1">点击目标的大小 <a class="header-anchor" href="#点击目标的大小" aria-label="Permalink to &quot;点击目标的大小&quot;">​</a></h2><p>框架的按钮判定区<strong>比视觉范围大</strong>。</p><table tabindex="0"><thead><tr><th>元素</th><th>视觉大小</th><th>判定大小</th></tr></thead><tbody><tr><td>悬浮窗</td><td>34 px</td><td>54 px</td></tr><tr><td>主按钮</td><td>高 30 px</td><td>高 46 px</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么「判定区外扩」很重要</p><p>手机上手指的接触面积比鼠标光标大得多。如果判定区和视觉范围一样大，玩家会觉得「明明点到了却没反应」。</p><p><strong>视觉上可以小（好看），但判定必须大（好点）。</strong></p><p>不过左右方向不做外扩 —— 否则相邻按钮会抢点击，反而更容易点错。</p></div><h2 id="面板操作" tabindex="-1">面板操作 <a class="header-anchor" href="#面板操作" aria-label="Permalink to &quot;面板操作&quot;">​</a></h2><h3 id="拖动面板" tabindex="-1">拖动面板 <a class="header-anchor" href="#拖动面板" aria-label="Permalink to &quot;拖动面板&quot;">​</a></h3><p><strong>拖动标题栏</strong>可以移动整个面板。</p><h3 id="切页" tabindex="-1">切页 <a class="header-anchor" href="#切页" aria-label="Permalink to &quot;切页&quot;">​</a></h3><p>点顶部标签切换六个页面。</p><div class="tip custom-block"><p class="custom-block-title">切页会清空确认状态</p><p>如果你在某页点了「删除」（进入确认状态），然后切到别的页，再切回来 —— <strong>确认状态已经清空了</strong>。</p><p>这是防止「点了一次、去干别的、回来手滑点到第二次」的误操作。</p></div><h3 id="滚动" tabindex="-1">滚动 <a class="header-anchor" href="#滚动" aria-label="Permalink to &quot;滚动&quot;">​</a></h3><p>每个页面都能上下滚动。内容超出屏幕时可以滑动查看。</p><h2 id="设计上刻意避免的东西" tabindex="-1">设计上刻意避免的东西 <a class="header-anchor" href="#设计上刻意避免的东西" aria-label="Permalink to &quot;设计上刻意避免的东西&quot;">​</a></h2><h3 id="不加「长按-n-秒」门槛" tabindex="-1">不加「长按 N 秒」门槛 <a class="header-anchor" href="#不加「长按-n-秒」门槛" aria-label="Permalink to &quot;不加「长按 N 秒」门槛&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">这是一个失败的教训</p><p>早期版本为了防止误触，加了「必须长按 0.3 秒才响应」的门槛。</p><p>结果：<strong>玩家完全打不开面板，而且没有任何提示说明要长按。</strong> 这个体验很糟。</p></div><p>现在的防误触策略是：</p><ul><li><strong>位置</strong> —— 建议放远离操作区的地方</li><li><strong>点窗外收起</strong> —— 点一下就收起，不会误触面板内的东西</li></ul><p><strong>而不是靠「响应门槛」。</strong></p><h3 id="倍速暂停档不进快捷循环" tabindex="-1">倍速暂停档不进快捷循环 <a class="header-anchor" href="#倍速暂停档不进快捷循环" aria-label="Permalink to &quot;倍速暂停档不进快捷循环&quot;">​</a></h3><p>悬浮窗上的倍速按钮循环是 <code>x1 → x2 → x3 → x1</code>，<strong>故意跳过了暂停（0）</strong>。</p><p>原因：误触到暂停会让<strong>所有游戏协程冻结</strong>，看起来像死机，玩家第一反应是「游戏挂了」。</p><p>所以不把暂停放在容易误点的位置。</p><h2 id="技巧汇总" tabindex="-1">技巧汇总 <a class="header-anchor" href="#技巧汇总" aria-label="Permalink to &quot;技巧汇总&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想做的事</th><th>怎么做</th></tr></thead><tbody><tr><td>打开面板</td><td>点悬浮窗（或三指同按）</td></tr><tr><td>挪位置</td><td>拖动悬浮窗 / 拖动面板标题栏</td></tr><tr><td>收起面板</td><td>点面板外面的灰色区域</td></tr><tr><td>找参数</td><td>展开对应分组，或用滚动</td></tr><tr><td>快速回原速</td><td>点悬浮窗旁的倍速按钮循环回 x1</td></tr><tr><td>打不开时</td><td><strong>三指同按屏幕</strong></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>六个页面 → <a href="/AtlanticFleetSite/docs/use/panel">游戏内控制台「小u」</a></li><li>倍速问题 → <a href="/AtlanticFleetSite/docs/use/timescale">倍速与时间缩放</a></li><li>点不动了 → <a href="/AtlanticFleetSite/docs/use/troubleshooting">出问题了怎么查</a></li></ul>',53)])])}const b=a(s,[["render",l]]);export{u as __pageData,b as default};
